const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const BASE_URL = 'http://127.0.0.1:4402/iframe.html?id=layout-zimmcartdrawer--default&viewMode=story';
const WIDTHS = [1186, 1279, 1280, 1350, 1440];
const HEIGHT = 1200;
const OUT_DIR = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad';

(async () => {
  const browser = await chromium.launch();
  try {
    for (const width of WIDTHS) {
      const context = await browser.newContext({ viewport: { width, height: HEIGHT } });
      const page = await context.newPage();
      await page.goto(BASE_URL, { waitUntil: 'networkidle' });
      await page.getByRole('dialog').waitFor({ state: 'visible', timeout: 15000 });
      await page.waitForTimeout(600);
      await page.screenshot({ path: `${OUT_DIR}/vw-${width}.png` });
      await context.close();
    }
  } finally {
    await browser.close();
  }
  console.log('done');
})().catch((err) => {
  console.error('SCRIPT FAILED:', err);
  process.exit(1);
});
